{
  "description": "The creature is a stout quadrupedal animal shown in right-facing profile standing on a small patch of bare ground. It has a broad, flat amphibian-like head with a large eye and pale underjaw, a thick barrel-shaped body and a long tapering tail. The entire dorsal surface including the top of the head, back, sides and top of the tail is covered in overlapping dark gray-brown keeled scales, while the belly, throat, underside of the tail and the limbs are smooth and pale gray to cream colored. Behind the head on both sides of the neck are multiple feathery external gill stalks with fine filaments. It stands on four short, stout limbs that end in broad splayed feet with small claws, and the tail extends straight back behind the body.",
  "parts": [
    {
      "part": "head",
      "looks_like": "broad, flat and blunt-snouted with a large round eye with dark pupil and light iris, a small nostril, and a pale cream underjaw and throat; the top and sides are covered in small overlapping scales",
      "where": "at the front right end of the body, facing right"
    },
    {
      "part": "gills",
      "looks_like": "six feathery external gill stalks with a central stem and many fine hair-like filaments along the edges, dark gray with reddish bases",
      "where": "three projecting from the right side of the neck just behind the head, and three visible projecting upward from the left side of the neck and back behind them"
    },
    {
      "part": "scales",
      "looks_like": "overlapping, rounded, keeled dark gray-brown scales with a glossy highlight, smaller and tighter on the head and larger on the back, sides and tail",
      "where": "covering the top of the head, the entire back and sides of the body, and the dorsal surface of the tail; absent on the belly, throat, underside of tail and limbs"
    },
    {
      "part": "legs",
      "looks_like": "four short, thick, smooth-skinned gray limbs with slightly darker shading, muscular and bent at the joints",
      "where": "two forelimbs under the chest and two hindlimbs under the rear of the body, supporting the body above the ground"
    },
    {
      "part": "feet",
      "looks_like": "broad splayed feet with five toes each ending in small dark pointed claws, with slight webbing between toes",
      "where": "at the end of each of the four legs, in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "long, thick at the base and tapering to a rounded point, scaled dark gray on top and smooth pale cream underneath with faint transverse ridges",
      "where": "extending straight back from the rear of the body to the right, lying on the ground behind the hind legs"
    }
  ],
  "attached_objects": [],
  "animals": [
    "axolotl",
    "pangolin"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0
}
